package studio.solocamera;
import org.json.*;
/** JVM checks use the production model/render choreography, without a device. */
public final class MotionPlacementTest {
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 static void close(double a,double b,String message){check(Math.abs(a-b)<.00001,message+": "+a+" != "+b);}
 static EditorProject.Clip legacy(int mode,boolean extra)throws Exception{EditorProject.Clip c=EditorTitlePresets.create(40,5000);long[] times={0,550,4450,5000};for(int i=0;i<4;i++){EditorMotion.Key k=new EditorMotion.Key();k.at=times[i];k.x=i==0&&mode==2?-.12:i==3&&mode==2?.1:0;k.y=i==0&&mode==1?-.55:-.5;k.scale=mode==3?(i==0?.88:i==3?.95:1):1;k.alpha=i==0||i==3?0:1;if(i==0){k.x1=.16;k.y1=1;k.x2=.3;k.y2=1;}c.keys.add(k);}if(extra){EditorMotion.Key k=new EditorMotion.Key();k.at=1600;k.x=.3;k.y=-.2;c.keys.add(k);c.keys.sort((a,b)->Long.compare(a.at,b.at));}JSONObject j=c.json();j.remove("titleMotion");return EditorProject.Clip.from(j);}
 public static void main(String[] args)throws Exception{
  for(int id=0;id<EditorTitlePresets.NAMES.length;id++){EditorProject.Clip c=EditorTitlePresets.create(id,5000);check(c.keys.isEmpty(),"Generated keys on preset "+id);EditorMotion.place(c,.1,-.2,1500,true);EditorMotion.scale(c,1.1,1500,true);for(long t=900;t<=4000;t+=173){EditorMotion.Key pose=EditorMotion.sample(c,t,true);close(pose.x,.1,"Preset X drift "+id);close(pose.y,-.2,"Preset Y drift "+id);close(pose.scale,1.1,"Preset scale drift "+id);}check(c.keys.isEmpty(),"Placement created keys");EditorProject.Clip saved=c.copy();check(saved.titleMotion==c.titleMotion&&saved.keys.isEmpty(),"Preset reload");close(EditorMotion.sample(saved,2500,true).x,.1,"Reload placement");EditorTitlePresets.animate(c,5000,0);close(EditorMotion.sample(c,0,true).alpha,1,"Still starts hidden");close(EditorMotion.sample(c,4999,true).x,.1,"Still moves");}
  for(int mode=1;mode<=3;mode++){EditorProject.Clip c=legacy(mode,false);check(c.titleMotion==mode&&c.keys.isEmpty(),"Legacy migration "+mode);EditorProject.Clip withUser=legacy(mode,true);check(withUser.titleMotion==mode&&withUser.keys.size()==1&&withUser.keys.get(0).at==1600,"Legacy user-key loss "+mode);EditorMotion.place(withUser,.4,-.1,2000,true);close(EditorMotion.sampleBase(withUser,3000,true).x,.4,"Migrated key movement");check(withUser.keys.size()==1,"Extra key on placement");}
  for(boolean text:new boolean[]{false,true}){EditorProject.Clip c=new EditorProject.Clip("test","Manual",5000);EditorMotion.Key first=EditorMotion.put(c,1000,text);first.x=.2;EditorMotion.Key second=EditorMotion.put(c,3000,text);second.x=1.3;second.y=-1.1;second.scale=.1;second.rotation=37;second.alpha=.6;c.opacity=.8;check(EditorMotion.remove(c,first,text)&&c.keys.size()==1,"Delete selected key");check(EditorMotion.remove(c,second,text)&&c.keys.isEmpty(),"Delete final key");EditorProject.Clip copy=c.copy();EditorMotion.Key pose=EditorMotion.sampleBase(copy,2500,text);close(pose.x,1.3,"Final key X reload");close(pose.y,-1.1,"Final key Y reload");close(pose.scale,.1,"Final key scale reload");close(pose.rotation,37,"Final key rotation reload");close(copy.opacity,.48,"Final key opacity reload");}
  EditorProject.Clip c=EditorTitlePresets.create(0,5000);EditorMotion.put(c,1000,true).x=.25;EditorMotion.put(c,3000,true).x=.5;EditorMotion.Key pose=EditorMotion.sampleBase(c,2000,true);EditorMotion.clear(c,2000,true);check(c.keys.isEmpty()&&c.titleMotion==1,"Clear removes built-in animation");close(c.textX,pose.x,"Clear placement");check(EditorMotion.nearest(c,1000,40)==null,"Deleted key still selectable");System.out.println("PASS 138 stable preset placements/scales, all legacy animation migrations, user-key retention, precise deletion, last-key pose/reload and clear-all");
 }
}
